--region logic

function OverManegeLoungeFeedNodes:FreshUI(isShow, isChangeViewState, loungeIndex, playerCardId, isStroke)
    self._isStroke = isStroke
    self:UpdateUIShowState(isShow, isChangeViewState)
    if not isShow then
        return
    end

    self._loungeIndex, self._playerCardId = loungeIndex, playerCardId
    self:FreshFeedNodes()
end

function OverManegeLoungeFeedNodes:FreshFeedNodes()
    local snackList = DataProvider:GetInstance():GetSnackList()
    for i, v in ipairs(snackList) do
        ---@type OverManegeLoungeFeedNode
        local nodeEnv = self._feedNodeEnvs[i]
        if isNull(nodeEnv) then
            local node = self[string.format("FeedNode%s", i)]
            nodeEnv    = CfUtils.GetLuaScr(node, MaidCoffeeConstants.EnvPath.OverManegeLoungeFeedNode)
            self._feedNodeEnvs[i] = nodeEnv
        end

        if not isNull(nodeEnv) then
            nodeEnv:FreshUI(v, self._responseRegions)
        end
    end
    
end

function OverManegeLoungeFeedNodes:UpdateUIShowState(isShow, isChangeViewState)
    if isChangeViewState then
        -- self.Content.enabled = false
        if isShow then
            self.Content:Play(Entry)
        end
        return
    end
    self.Content:Play(Idle)
end

