--region handler

function OverManegeLoungeFeedNodes:OnClickBtnAction()
    if not DataProvider:GetInstance():CheckSnackList() then
        GameUtils.Toast(localize("当前没有可使用的零食"))
        return
    end

    if self._playerCardId ~= nil and DataProvider:GetInstance():CheckIsMaxEnergy(self._playerCardId) then
        GameUtils.Toast(localize("该卡牌心情已满"))
        return
    end

    local isCanRecovery = DataProvider:GetInstance():CheckRoomCardFeedCondition(self._loungeIndex)
    if isCanRecovery then
        DataProvider:GetInstance():RequestLoungeFeedAll(self._loungeIndex, self._playerCardId, self._isStroke)

    else
        GameUtils.Toast(localize("该孵化室暂无可使用零食的卡牌"))
        
    end

end

